INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷102·隐帝本纪·乾祐二年七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-102-july-949/source.txt", "note": "《旧五代史》卷102·隐帝本纪·乾祐二年七月，段落 jiu-wudaishi-205deb4a7860-p002476；已核上下文及传主，纸本及异文待核。", "id": "e9c5c4ee-ffa8-5a06-8b68-2066e08a21e4"}, {"title": "旧五代史·卷107·郭允明传", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-107-guo-yunming/source.txt", "note": "《旧五代史》卷107·郭允明传，段落 jiu-wudaishi-205deb4a7860-p002578；已核上下文及传主，纸本及异文待核。", "id": "d1cf4c37-63c4-56b5-9e5c-ba1049b77366"}, {"title": "旧五代史·卷107·后赞传·飞龙使", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-107-hou-zan/source.txt", "note": "《旧五代史》卷107·后赞传·飞龙使，段落 jiu-wudaishi-205deb4a7860-p002576；已核上下文及传主，纸本及异文待核。", "id": "96e457b4-14a0-5169-9811-f5b08a843bb9"}, {"title": "旧五代史·卷125·王守恩传·洛阳聚敛与被替换", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-125-wang-shouen-luoyang/source.txt", "note": "《旧五代史》卷125·王守恩传·洛阳聚敛与被替换，段落 jiu-wudaishi-205deb4a7860-p002915；已核上下文及传主，纸本及异文待核。", "id": "d2c3a64e-3a3b-50ec-84e8-b9e06acd8864"}, {"title": "旧五代史·卷125·王守恩传·《五代史补》注引洛阳易留守", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2d42e21ad1bb401f000e13eff449c033474939df/content/books/zizhi-tongjian/vol-288/year-0949/part-03/sources/library/jiuwudaishi-125-wang-shouen-note/source.txt", "note": "《旧五代史》卷125·王守恩传·《五代史补》注引洛阳易留守，段落 jiu-wudaishi-205deb4a7860-p002916；已核上下文及传主，纸本及异文待核。", "id": "ebb14d8b-684f-5972-85b8-c4ef4ac96c4f"}, {"title": "资治通鉴·卷288·乾祐二年·六月至八月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/tongjian-288-949-june-july/source.txt", "note": "《资治通鉴》卷288·乾祐二年·六月至八月，段落 zizhi-tongjian-a63549944a71-p003424；已核上下文及传主，纸本及异文待核。", "id": "a9b57512-1ba4-5b10-b3c3-6a8f96e53250"}, {"title": "宋史·巻二百六十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/60d249b7/content/books/zizhi-tongjian/vol-275/year-0926/part-01/sources/library/songshi-263-926-zhangzhao-name/source.txt", "note": "《宋史》巻二百六十三，段落 songshi-9c6e46fee832-p058227；EPUB电子本，纸本及异文待核", "id": "f08606c3-787e-5d67-9e23-68b163a3c891"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "后匡赞", "aliases": ["后赞", "後贊", "後匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "瑕丘人，后汉飞龙使。949年条下与郭允明一起见于刘承祐近臣的记载。《旧五代史》写后赞，官职及朝廷人物背景相合，本批保留这个异名。生卒年尚未录入。", "biography": null, "status": "draft", "id": "ad25a35f-89f7-538f-8c83-ffe2d366f2ff"}, {"name": "郭允明", "aliases": ["窦十", "竇十"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原、河东人，小名窦十。曾在刘知远身边服役，后来担任翰林茶酒使兼鞍辔库使。949年为刘承祐近臣，《通鉴》和《旧五代史》都记其受宠。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3bedf030-0a2d-5884-8dd9-eec11a8c4ccc"}, {"name": "李氏（刘知远妻）", "aliases": ["李氏（後漢高祖后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，刘知远的妻子。947年二月劝丈夫停止征民财劳军，改用宫中积蓄，建议获采纳。《旧五代史》称高祖皇后李氏，此时《通鉴》称夫人李氏，正式册后另在后续时间录入。名字与生卒年暂未录入。", "biography": null, "status": "draft", "id": "10b635fe-af1e-534c-891a-5b82288872e1"}, {"name": "张昭（五代宋初）", "aliases": ["张昭远", "張昭遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：张昭（五代宋初），河间推官、劝表并赞志者。", "biography": null, "status": "draft", "id": "0f1b47dc-df4b-5258-91b3-463432d576b7"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "扈彦珂", "aliases": ["扈彥珂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉镇国节度使。948年郭威督军讨伐三镇时，建议先攻作为盟主的李守贞，避免先攻长安、凤翔而腹背受敌，郭威采纳。生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "b3dfa0c2-3df0-5a4f-8c4b-33791166e22a"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李德明", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐尚书员外郎。949年条下与钟谟一起参与国政，史书记两人受李璟宠信，但不是魏岑的同党。生卒年尚未录入。", "biography": null, "status": "draft", "id": "3aa99691-05a6-5807-a0c3-f56c9cebb4f1"}, {"name": "范冲敏", "aliases": ["范沖敏"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "南唐户部员外郎。949年劝王建封上书批评执政者、请求任用正直之人，随后被李璟处死。生年与此前经历未载。", "biography": null, "status": "draft", "id": "476cff76-29f1-53dc-9095-5179a0ffe54e"}, {"name": "王建封", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "上元人，南唐将领。945年《资治通鉴》记他以先锋桥道使身份率先登上建州城墙，南唐军随后攻破建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "a7b5c6e1-9057-52ff-8317-f82698daacd6"}, {"name": "舒元", "aliases": ["朱元", "硃元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沈丘人，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓朱，赴南唐求援。《新五代史》记求援者为朱元。生卒年尚未确定。", "biography": null, "status": "draft", "id": "4747ce90-dd4b-5e0b-a0c8-7420788a2347"}, {"name": "杨讷", "aliases": ["楊訥", "李平"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "嵩山道士，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓李、名平，与舒元通过隐秘道路到南唐求援。生卒年未载。", "biography": null, "status": "draft", "id": "2e43b907-5e6b-52bd-8ad9-35801725e3b9"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "钱弘亿", "aliases": ["錢弘億"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲姓名本句未载。939年条下的王室家属追述提及他，出生年份未载。", "biography": null, "status": "draft", "id": "11129a7d-ca77-5d63-b3fd-b341fb184b7e"}, {"name": "王守恩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王建立的儿子，与张从恩是姻亲。947年在上党，以左骁卫大将军身份被张从恩暂派为巡检使，协助赵行迁。姻亲具体双方未明，不补具体婚配，生卒年未载。", "biography": null, "status": "draft", "id": "72fe9a16-4716-54d0-bc82-5e7feadc013e"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "白文珂", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋代州刺史。944年九月在七里烽击败契丹；新史记丙子，旧史壬辰记录太原奏报。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "4144a98b-cc52-5b8e-afec-6ad9ed55b845"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

